package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamModern43GroupBank1 {
    private const val T = "නූතන බටහිර කලාව හා ශ්‍රී ලංකාවේ '43 කණ්ඩායම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("19 වන සියවසේ ප්‍රංශයේ බිහි වූ නූතන චිත්‍ර කලාවේ ආරම්භක ව්‍යාපාරය වන 'උපස්ථිතිවාදයට' (Impressionism) එම නම ලැබුණේ කුමන සිතුවම නිසාද?", "මොනේගේ 'ඉම්ප්‍රෙෂන් සන්රයිස්'", "පිකාසෝගේ 'ගුවර්නිකා'", "වෑන් ගෝගේ 'තාරකා රාත්‍රිය'", "එඩ්වඩ් මන්ච්ගේ 'විලාපය'", "1874 ප්‍රදර්ශනයේදී මොනේගේ සිතුවම විවේචනය කරමින් විචාරකයෙකු යෙදූ නම පසුව ව්‍යාපාරයේ නම විය."),
        q("උපස්ථිතිවාදී (Impressionist) චිත්‍ර ශිල්පීන් චිත්‍රාගාරයෙන් පිටතට ගොස් ස්වභාවික ආලෝකය යටතේ එළිමහනේ චිත්‍ර ඇඳීමේ ක්‍රමය කුමක්ද?", "එළිමහන් චිත්‍රකරණය (En Plein Air)", "ටෙනෙබ්‍රිසම් තාක්ෂණය", "ෆ්‍රෙස්කෝ බුඕනෝ ක්‍රමය", "ස්ෆුමාටෝ වර්ණ මිශ්‍රණය", "මොහොතින් මොහොත වෙනස් වන හිරු එළිය හා වර්ණ පරාවර්තන ක්ෂණිකව අල්ලා ගැනීමට එළිමහනේ ඇන්දහ."),
        q("උපස්ථිතිවාදී චිත්‍ර ශිල්පීන් සෙවණැලි ඇඳීමේදී පැරණි කලාකරුවන් මෙන් කළු වර්ණය නොයොදා භාවිත කළේ කුමක්ද?", "නිල්, දම් වැනි අනුපූරක වර්ණ", "තද ගල් අඟුරු කළු තීන්ත", "පිරිසිදු සුදු වර්ණ ස්තර", "රන් හා රිදී පත්‍ර කැබලි", "ආලෝකයේ ස්වභාවය නිරීක්ෂණය කරමින් සෙවණැලි තුළ පවා වර්ණ පවතින බව ඔවුහු පෙන්වූහ."),
        q("වතුර මල්, කුමුදු මල් පොකුණ (Water Lilies) සහ රූවන් දෙව්මැදුර විවිධ වේලාවන්හි ආලෝකය යටතේ සිතුවම් කළ උපස්ථිතිවාදී නායකයා කවුද?", "ක්ලෝඩ් මොනේ (Claude Monet)", "පැබ්ලෝ පිකාසෝ", "සැල්වදෝර් ඩාලි", "ඇන්ඩි වෝහෝල්", "ගිවර්නි උද්‍යානයේ මානෙල් පොකුණු සිතුවම් මාලාව මොනේගේ වර්ණ හා ආලෝක අධ්‍යයනයේ උච්චතම අවස්ථාවයි."),
        q("බැලේ නර්තන ශිල්පිනියන්, තුරඟ තරග සහ අසමමිතික ඡායාරූප රාමු ආකාරයෙන් සිතුවම් ඇඳි ප්‍රංශ උපස්ථිතිවාදී ශිල්පියා කවුද?", "එඩ්ගා ඩෙගාස් (Edgar Degas)", "පෝල් ගොගෑන්", "වැසිලි කැන්ඩින්ස්කි", "පියෙට් මොන්ඩ්‍රියන්", "ජපන් මුද්‍රණ හා ඡායාරූප ආභාසයෙන් ඩෙගාස් පැස්ටල් හා තෙල් සායම් මගින් නැටුම් චලන සිතුවම් කළේය."),
        q("ප්‍රීතිමත් ජන සමාජ අවස්ථා, උද්‍යාන භෝජන ('බෝට්ටු සාදයේ දිවා ආහාරය') හා මෘදු හිරු එළිය සිතුවම් කළ ප්‍රංශ උපස්ථිතිවාදී ශිල්පියා කවුද?", "පියෙර්-ඔගස්ට් රෙනෝයා", "එඩ්වඩ් මන්ච්", "ෆ්‍රාන්ස් මාර්ක්", "මාර්සෙල් ඩුෂාම්ප්", "ජීවිතයේ සුන්දරත්වය හා මිනිස් උණුසුම රෙනෝයාගේ දීප්තිමත් වර්ණ පින්සල් පහරවලින් ප්‍රකාශ වේ."),
        q("උපස්ථිතිවාදයට මග පෑදූ 'තණකොළ මත දිවා ආහාරය' සහ 'ඔලිම්පියා' සිතුවම් ඇඳ සම්ප්‍රදායික ඇකඩමි නීති කඩ කළ පුරෝගාමියා කවුද?", "එඩුවාර් මැනේ (Édouard Manet)", "ලියනාඩෝ ඩා වින්චි", "හොකුසායි", "ජෝර්ජ් සෝරා", "නූතන නාගරික ජීවිතය හා පැතලි වර්ණ භාවිතය නිසා මැනේ නූතන චිත්‍ර කලාවේ පියා ලෙස හැඳින්වේ."),
        q("කුඩා පිරිසිදු වර්ණ තිත් (Dots) කැන්වසය මත ලං ලංව තබා ඇසෙන් මිශ්‍ර වන 'පොයින්ටිලිසම්' (Pointillism) ක්‍රමය සොයා ගත්තේ කවුද?", "ජෝර්ජ් සෝරා (Georges Seurat)", "ක්ලෝඩ් මොනේ", "සැල්වදෝර් ඩාලි", "පෝල් සෙසෑන්", "'ලා ග්‍රෑන්ඩ් ජැට් දූපතේ ඉරිදා දහවලක්' සිතුවම සෝරා විද්‍යාත්මක වර්ණ තිත් ක්‍රමයෙන් නිමවීය."),
        q("උපස්ථිතිවාදයේ සීමාවන් ඉක්මවා චිත්‍රයට හැඟීම්, ආකෘතිය හා සංකේත එක් කළ 'පශ්චාත් උපස්ථිතිවාදී' (Post-Impressionist) ප්‍රධාන ශිල්පීන් තිදෙනා කවුද?", "වින්සන්ට් වෑන් ගෝ, පෝල් සෙසෑන් සහ පෝල් ගොගෑන්", "ඩා වින්චි, රැෆායෙල් සහ මයිකල් ආන්ජලෝ", "ඩේවිඩ්, ඉන්ග්‍රේ සහ කෝබේ", "වෝහෝල්, පොලොක් සහ රොත්කෝ", "වෑන් ගෝ ප්‍රකාශනයටත්, සෙසෑන් ජ්‍යාමිතික ආකෘතියටත්, ගොගෑන් සංකේත වර්ණයටත් පාර කැපූහ."),
        q("'තාරකා රාත්‍රිය' (The Starry Night) සහ 'සූරියකාන්ත මල්' වැනි අතිශය හැඟීම්බර ඝන පින්සල් පහර සහිත සිතුවම් නිර්මාණය කළ ලන්දේසි ශිල්පියා කවුද?", "වින්සන්ට් වෑන් ගෝ", "ක්ලෝඩ් මොනේ", "පැබ්ලෝ පිකාසෝ", "පෝල් සෙසෑන්", "කැරකෙන තීන්ත රටා හා දීප්තිමත් කහ-නිල් වර්ණ මගින් වෑන් ගෝ තම අභ්‍යන්තර මානසික හැඟීම් ප්‍රකාශ කළේය."),
        q("'නූතන කලාවේ පියා' ලෙස හඳුන්වනු ලබන, ස්වභාවධර්මය සිලින්ඩර, ගෝල හා කේතු මගින් දුටු ප්‍රංශ පශ්චාත් උපස්ථිතිවාදී ශිල්පියා කවුද?", "පෝල් සෙසෑන් (Paul Cézanne)", "එඩ්ගා ඩෙගාස්", "විලියම් ටර්නර්", "ඇන්ඩි වෝහෝල්", "සෙන්ට්-වික්ටොයාර් කන්ද හා ඇපල් නිශ්චල සිතුවම් හරහා සෙසෑන් කියුබිසම් ව්‍යාපාරයට මූලික අඩිතාලම දැමීය."),
        q("යුරෝපීය කාර්මික සමාජය හැරදා ටහීටි දූපතට ගොස් සරල හා ප්‍රබල සංකේතාත්මක වර්ණ පැතලි ලෙස යොදා සිතුවම් ඇඳි ශිල්පියා කවුද?", "පෝල් ගොගෑන් (Paul Gauguin)", "ජෝර්ජ් සෝරා", "ජැක්-ලුවී ඩේවිඩ්", "රෙනෝයා", "විදේශීය හා ප්‍රාථමික සමාජ වර්ණ යොදා ගනිමින් ගොගෑන් ප්‍රකාශනවාදයට මග පෑදුවේය."),
        q("20 වන සියවස මුලදී වස්තූන්ගේ ස්වභාවික පැහැය නොසලකා 'තද වල් වර්ණ' (Wild Beasts) භාවිත කළ හෙන්රි මැටිස්ගේ ව්‍යාපාරය කුමක්ද?", "ෆෝවිසම් (Fauvism)", "කියුබිසම්", "යථාර්ථවාදය", "බැරොක්", "'රතු කාමරය' හා 'හරිත රේඛාව' නිර්මාණය කළ මැටිස් වර්ණයේ සම්පූර්ණ නිදහස ෆෝවිසම් මගින් ප්‍රකාශ කළේය."),
        q("නෝර්වීජියානු ශිල්පී එඩ්වඩ් මන්ච් (Edvard Munch) විසින් නූතන මිනිසාගේ මානසික බිය හා ආතතිය දක්වමින් ඇඳි ප්‍රකට ප්‍රකාශනවාදී සිතුවම කුමක්ද?", "විලාපය (The Scream)", "මොනාලිසා", "ගුවර්නිකා", "වීනස්ගේ උපත", "රතු තැඹිලි අහස යට පාලම මත කෑගසන රුව 20 වන සියවසේ ප්‍රකාශනවාදයේ (Expressionism) සංකේතයකි."),
        q("ජර්මානු ප්‍රකාශනවාදයේ ප්‍රධාන කණ්ඩායම් දෙක වන 'ඩයි බෲක්' (Die Brücke - පාලම) සහ 'ඩර් බ්ලවු රයිටර්' (Der Blaue Reiter - නිල් අසරුවා) අවධාරණය කළේ කුමක්ද?", "ආත්මීය හැඟීම් හා තියුණු වර්ණ", "සම්භාව්‍ය ග්‍රීක පිළිම පිටපත් කිරීම", "පැරණි ෆ්‍රෙස්කෝ බිතුසිතුවම් ඇඳීම", "වෙළඳ දැන්වීම් ඡායාරූප සැකසීම", "කර්ච්නර්, කැන්ඩින්ස්කි හා ෆ්‍රාන්ස් මාර්ක් ජර්මානු ප්‍රකාශනවාදයට නායකත්වය දුන්හ."),
        q("වස්තුවක් එකවර විවිධ කෝණවලින් (Multi-perspective) බලා ජ්‍යාමිතික තලවලට කඩා නැවත ගොඩනගන කලා ව්‍යාපාරය කුමක්ද?", "කියුබිසම් හෙවත් ඝනවාදය (Cubism)", "උපස්ථිතිවාදය", "අධියථාර්ථවාදය", "රොමෑන්ටික්වාදය", "1907 දී පැබ්ලෝ පිකාසෝ හා ජෝර්ජ් බ්‍රාක් එක්ව 'ඇවිග්නොන්හි යුවතියෝ' සමඟ කියුබිසම් ඇරඹූහ."),
        q("කියුබිසම් ව්‍යාපාරයේ නිර්මාතෘවරුන් දෙදෙනා ලෙස සැලකෙන කලාකරුවන් යුගලය කවුද?", "පැබ්ලෝ පිකාසෝ සහ ජෝර්ජ් බ්‍රාක්", "මොනේ සහ රෙනෝයා", "වෑන් ගෝ සහ ගොගෑන්", "ඩාලි සහ මැග්‍රිට්", "විශ්ලේෂණාත්මක කියුබිසම් (Analytical) හා සංශ්ලේෂණාත්මක කියුබිසම් (Synthetic) හරහා ඔවුන් කලාව වෙනස් කළහ."),
        q("1937 දී ස්පාඤ්ඤ සිවිල් යුද්ධයේ ගුවන් බෝම්බ ප්‍රහාරය හෙළා දකිමින් පැබ්ලෝ පිකාසෝ කළු, සුදු සහ අළු පැහැයෙන් ඇඳි මහා සිතුවම කුමක්ද?", "ගුවර්නිකා (Guernica)", "මොනාලිසා", "තාරකා රාත්‍රිය", "වසන්තය", "වධ හිංසාවට පත් මිනිසුන්, අශ්වයා හා ගොනා යොදා ගුවර්නිකා සිතුවම යුද විරෝධී කලා සංකේතයක් බවට පත් විය."),
        q("සංශ්ලේෂණාත්මක කියුබිසම් (Synthetic Cubism) යුගයේදී පිකාසෝ හා බ්‍රාක් විසින් කැන්වසය මත පුවත්පත් කැබලි හා කඩදාසි ඇලවීමෙන් හඳුන්වා දුන් ක්‍රමය කුමක්ද?", "කොලාජ් (Collage - Papier Collé)", "ෆ්‍රෙස්කෝ", "ස්ෆුමාටෝ", "ටෙම්පරා", "සැබෑ ජීවිතයේ කඩදාසි, ලී කුඩු හා රෙදි කැබලි චිත්‍රයට එක් කිරීම නූතන මිශ්‍ර මාධ්‍ය කලාවට මග පෑදීය."),
        q("මුල්ම සම්පූර්ණ වියුක්ත (Abstract / Non-representational) චිත්‍ර ශිල්පියා ලෙස සැලකෙන රුසියානු ශිල්පියා කවුද?", "වැසිලි කැන්ඩින්ස්කි", "පෝල් සෙසෑන්", "ජෝර්ජ් සෝරා", "හෙන්රි මැටිස්", "සංගීතය මෙන්ම වර්ණ හා හැඩතලද හඳුනාගත හැකි වස්තු රහිතව අභ්‍යන්තර හැඟීම් ජනිත කරන බව කැන්ඩින්ස්කි පෙන්වීය."),
        q("ලන්දේසි 'ඩි ස්ටිජ්ල්' (De Stijl) ව්‍යාපාරයේ සිරස්-තිරස් කළු රේඛා හා රතු, නිල්, කහ ප්‍රාථමික වර්ණ කොටු පමණක් යොදා සිතුවම් කළ ශිල්පියා කවුද?", "පියෙට් මොන්ඩ්‍රියන්", "වින්සන්ට් වෑන් ගෝ", "එඩ්ගා ඩෙගාස්", "ක්ලෝඩ් මොනේ", "නියෝ-ප්ලාස්ටිසිසම් නමින් මොන්ඩ්‍රියන් ඉතා පිරිසිදු ජ්‍යාමිතික සමතුලිතතාව ගොඩනැගීය."),
        q("පළමු ලෝක යුද්ධයේ විනාශයට එරෙහිව තර්ක බුද්ධිය ප්‍රතික්ෂේප කරමින් 'සූදානම් කළ භාණ්ඩ' (Ready-mades) කලාගාරයට ගෙන ආ ව්‍යාපාරය කුමක්ද?", "ඩාඩාවාදය (මාර්සෙල් ඩුෂාම්ප්)", "පුනරුද ෆ්‍රෙස්කෝ ව්‍යාපාරය", "නව-සම්භාව්‍යවාදය", "බැරොක් කලා සම්ප්‍රදාය", "සාම්ප්‍රදායික කලා නිර්වචන ප්‍රශ්න කළ ඩුෂාම්ප් චින්තනය නූතන සංකල්පීය කලාවට මුල් විය."),
        q("සිග්මන්ඩ් ෆ්‍රොයිඩ්ගේ මනෝවිශ්ලේෂණවාදය ඇසුරෙන් සිහින ලෝක, උපවිඥානය හා තර්කයට පටහැනි අද්භූත දසුන් සිතුවම් කළ කලා ව්‍යාපාරය කුමක්ද?", "අධියථාර්ථවාදය (Surrealism)", "යථාර්ථවාදය", "උපස්ථිතිවාදය", "ෆෝවිසම්", "සැල්වදෝර් ඩාලි, රෙනේ මැග්‍රිට් හා ජෝන් මිරෝ අධියථාර්ථවාදී කලාවේ ප්‍රධාන නියෝජිතයෝ වෙති."),
        q("දිය වී වැගිරෙන ඔරලෝසු සහිත 'මතකයේ ස්ථිරභාවය' (The Persistence of Memory) සිතුවම නිර්මාණය කළ සුප්‍රකට අධියථාර්ථවාදී ශිල්පියා කවුද?", "සැල්වදෝර් ඩාලි (Salvador Dalí)", "ක්ලෝඩ් මොනේ", "ජැක්සන් පොලොක්", "ජෝර්ජ් කීට්", "ස්පාඤ්ඤ ජාතික ඩාලි අතිශය සියුම් යථාර්ථවාදී තාක්ෂණයකින් සිහින හා විකාරරූපී දසුන් මැවීය."),
        q("'මෙය පයිප්පයක් නොවේ' යනුවෙන් පයිප්පයක රූපයක් යටින් ලියා රූපය හා භාෂාව අතර වෙනස පෙන්වූ බෙල්ජියම් අධියථාර්ථවාදී ශිල්පියා කවුද?", "රෙනේ මැග්‍රිට් (René Magritte)", "වින්සන්ට් වෑන් ගෝ", "ලියනාඩෝ ඩා වින්චි", "හෙන්රි මැටිස්", "එදිනෙදා වස්තු අසාමාන්‍ය ලෙස ගළපමින් මැග්‍රිට් නරඹන්නාගේ තර්කනය අභියෝගයට ලක් කළේය."),
        q("දෙවන ලෝක යුද්ධයෙන් පසු ඇමරිකාවේ නිව්යෝර්ක් නගරයේ බිහි වූ, බිම එළූ කැන්වසය මත තීන්ත වත් කර විසුරුවන 'ඇක්ෂන් පේන්ටිං' (Action Painting) ශිල්පියා කවුද?", "ජැක්සන් පොලොක් (Jackson Pollock)", "ඇන්ඩි වෝහෝල්", "රැෆායෙල්", "මයිකල් ආන්ජලෝ", "වියුක්ත ප්‍රකාශනවාදයේ (Abstract Expressionism) නියමුවෙකු වූ පොලොක්ගේ ශරීර චලනය චිත්‍රයේ කොටසක් විය."),
        q("කැම්බල් සුප් ටින්, කොකා-කෝලා බෝතල් හා මැරිලින් මොන්රෝගේ සිල්ක් ස්ක්‍රීන් මුද්‍රණ හරහා ජනප්‍රිය සංස්කෘතිය කලාවට ගෙන ආ 'පොප් කලා' (Pop Art) නායකයා කවුද?", "ඇන්ඩි වෝහෝල් (Andy Warhol)", "වැසිලි කැන්ඩින්ස්කි", "සැල්වදෝර් ඩාලි", "ජොටෝ", "වෝහෝල් සහ රෝයි ලිච්ටන්ස්ටයින් 1960 දශකයේදී වෙළඳ දැන්වීම් හා කොමික් චිත්‍ර කලාගාරයට ගෙන ආහ."),
        q("ශ්‍රී ලංකාවේ නූතන චිත්‍ර කලා ඉතිහාසයේ විප්ලවීය සංධිස්ථානය වූ '43 කණ්ඩායම' ('43 Group) පිහිටුවන ලද්දේ කුමන වර්ෂයේද?", "1943 වර්ෂයේ අගෝස්තු මාසයේදී", "1843 වර්ෂයේදී", "1973 වර්ෂයේදී", "1903 වර්ෂයේදී", "බ්‍රිතාන්‍ය ඇකඩමික් සිලෝන් සොසයිටි ඔෆ් ආර්ට්ස් සම්ප්‍රදායෙන් බිඳී 1943 දී මෙම කණ්ඩායම බිහිවිය."),
        q("ශ්‍රී ලංකාවේ '43 කණ්ඩායම පිහිටුවීමේ ප්‍රධාන සංවිධායකවරයා, ඡායාරූප ශිල්පියා සහ කලා විචාරකයා ලෙස කටයුතු කළේ කවුද?", "ලයනල් වෙන්ඩ්ට් (Lionel Wendt)", "ඒ.සී.ජී.එස්. අමරසේකර", "සොලියස් මෙන්ඩිස්", "ඩී.එස්. සේනානායක", "කොළඹ ගිල්ඩ්ෆර්ඩ් චන්ද්‍රවංකයේ පිහිටි ලයනල් වෙන්ඩ්ට්ගේ නිවසේදී '43 කණ්ඩායම ආරම්භ කෙරිණි."),
        q("'43 කණ්ඩායමේ ප්‍රධානතම අරමුණ වූයේ කුමක්ද?", "ලාංකේය නූතන කලාවක් බිහි කිරීම", "මහනුවර බිතුසිතුවම් පමණක් පිටපත් කිරීම", "බටහිර ඇකඩමික් සම්ප්‍රදායම රැකීම", "යුරෝපීය කිරිගරුඬ මූර්ති ආනයනය", "පෙරදිග සාම්ප්‍රදායික ආත්මය හා පශ්චාත්-උපස්ථිතිවාදී/කියුබිස්ට් නූතන ශිල්ප ක්‍රම ඔවුහු සංකලනය කළහ."),
        q("'43 කණ්ඩායමේ ජාත්‍යන්තර කීර්තියට පත් වූ, බොරැල්ල ගෝතමී විහාරයේ බිතුසිතුවම් ඇඳි ශ්‍රේෂ්ඨ ශ්‍රී ලාංකේය චිත්‍ර ශිල්පියා කවුද?", "ජෝර්ජ් කීට් (George Keyt)", "හැරී පීරිස්", "අයිවන් පීරිස්", "ඩේවිඩ් පේන්ටර්", "භාරතීය හා කැන්ඩියන් කාව්‍ය රසය පිකාසෝ ආභාසිත කියුබිස්ට් රේඛා සමඟ මුසු කළ අග්‍රගණ්‍ය ශිල්පියා කීට්ය."),
        q("ජෝර්ජ් කීට් විසින් බොරැල්ල ගෝතමී විහාරයේ සිතුවම් කර ඇති ප්‍රධාන තේමාව කුමක්ද?", "සිද්ධාර්ථ බෝසත් හා බුද්ධ චරිතය", "රාමායණ මහා කාව්‍ය සිදුවීම්", "යුරෝපීය කාර්මික නගර දසුන්", "ශ්‍රී ලංකාවේ ගැමි වෙළඳපොළ දසුන්", "නූතන ලාංකේය විහාර චිත්‍ර කලාවේ හැරවුම් ලක්ෂ්‍යයක් ලෙස 1939–1940 දී ගෝතමී විහාර සිතුවම් නිමවීය."),
        q("ජෝර්ජ් කීට්ගේ චිත්‍රවල දැකිය හැකි සුවිශේෂී කලාත්මක ලක්ෂණ මොනවාද?", "ලයාන්විත රේඛා හා උණුසුම් වර්ණ", "සියුම් ඡායාරූප යථාර්ථවාදී බව", "තනි කළු-සුදු තිත් රටා පමණක්", "පැතලි චීන තීන්ත පහර පමණක්", "'නායිකා', 'ගීත ගෝවින්ද', 'කංසා වධය' වැනි කීට්ගේ කෘති රිද්මයානුකූල රේඛා හා හැඟීම් ප්‍රකාශනයෙන් අනූනය."),
        q("'43 කණ්ඩායමේ ආරම්භක සාමාජිකයෙකු හා සපුමල් පදනම (Sapumal Foundation) බිහි කළ ශ්‍රේෂ්ඨ ආලේඛ්‍ය චිත්‍ර ශිල්පියා කවුද?", "හැරී පීරිස් (Harry Pieris)", "ජෝර්ජ් කීට්", "ජස්ටින් දැරණියගල", "මංජු ශ්‍රී", "ලන්ඩන් හා පැරිස්හි කලාව හැදෑරූ හැරී පීරිස් විශිෂ්ට මානව ආලේඛ්‍ය සිතුවම් ඇන්ද අතර කණ්ඩායමේ ලේකම්ද විය."),
        q("'43 කණ්ඩායමේ සාමාජිකයෙකු වූ 'ජස්ටින් දැරණියගල' (Justin Daraniyagala) වෙනීස් බියෙනාලේ (Venice Biennale) උළෙලේදී පැසසුමට ලක් වූයේ කුමන ශෛලියක් නිසාද?", "ප්‍රකාශනවාදී ඝන තීන්ත ආලේපය", "මහනුවර තීරු සිතුවම් ක්‍රමය", "සියුම් ජල සායම් මල් සිතුවම්", "පෞරාණික කළුගල් කැටයම් කලාව", "'මත්ස්‍ය වෙළෙන්දිය' වැනි ජස්ටින් දැරණියගලගේ කෘති යටි සිතේ ගැඹුරු මානව හැඟීම් පළ කරයි."),
        q("ශ්‍රී ලංකාවේ '43 කණ්ඩායමේ ප්‍රමුඛ භූ දර්ශන හා ජීව චිත්‍ර ශිල්පියෙකු වූ 'අයිවන් පීරිස්' (Ivan Pieris) බොහෝ විට සිතුවම් කළේ මොනවාද?", "වෙරළබඩ භූ දර්ශන හා ධීවර ඔරු", "නාගරික යුද හා සටන් දර්ශන", "වියුක්ත කළු ජ්‍යාමිතික කොටු", "විශාල කාර්මික ගොඩනැගිලි", "සංයමයෙන් යුත් සෞම්‍ය වර්ණ තල හා සරල ආකෘති අයිවන් පීරිස්ගේ නිර්මාණවල විශේෂත්වයයි."),
        q("'43 කණ්ඩායමේ සාමාජිකයෙකු මෙන්ම ප්‍රකට දේශපාලන කාටූන් ශිල්පියෙකු ලෙසද කීර්තියක් දැරූ කලාකරුවා කවුද?", "ඕබ්‍රි කොලට් (Aubrey Collette)", "රිචඩ් ගේබ්‍රියෙල්", "හැරී පීරිස්", "ජෝර්ජ් කීට්", "කෙටි හා තියුණු රේඛා කිහිපයකින් සමාජ උපහාසය හා ජීවගුණය ගෙන ඒමට ඕබ්‍රි කොලට් දක්ෂ විය."),
        q("'43 කණ්ඩායමේ ක්‍රිස්තියානි හා ගැමි ලාංකේය තේමා ඉතා සංවේදීව හා අවම රේඛා-වර්ණ මගින් සිතුවම් කළ කලාකරුවා කවුද?", "රිචඩ් ගේබ්‍රියෙල්", "ලයනල් වෙන්ඩ්ට්", "එල්.ටී.පී. මංජු ශ්‍රී", "මුදලියාර් අමරසේකර", "ගවයන්, ධීවරයන් හා කිතුනු පවුල් දර්ශන අලංකාර වර්ණ තල හා ලී මුද්‍රණ මගින් රිචඩ් ගේබ්‍රියෙල් ඇන්දේය."),
        q("'43 කණ්ඩායමේ සාමාජිකයෙකු වූ 'එල්.ටී.පී. මංජු ශ්‍රී' (L.T.P. Manjusri) ලාංකේය කලා ඉතිහාසයට කළ අනුපමේය සේවය කුමක්ද?", "විහාර බිතුසිතුවම් පිටපත් කිරීම", "පළමු කැන්වස් කර්මාන්තශාලාව ඇරඹීම", "ග්‍රීක කිරිගරුඬ මූර්ති පිටපත් කිරීම", "ලී මුද්‍රණ යන්ත්‍ර නිපදවීම", "ශාන්තිනිකේතනයේ ඉගෙන ගත් මංජු ශ්‍රී හිමි නමක්ව සිටියදී පැරණි විහාර සිතුවම් පිටපත් රැසක් ආරක්ෂා කළේය."),
        q("'43 කණ්ඩායමට පෙර ශ්‍රී ලංකාවේ බටහිර ඇකඩමික් (Academic Realism) සම්ප්‍රදායේ පුරෝගාමී ජල සායම් හා තෙල් සායම් චිත්‍ර ශිල්පියා කවුද?", "ඒ.සී.ජී.එස්. අමරසේකර", "ජෝර්ජ් කීට් ශිල්පියා", "ජස්ටින් දැරණියගල", "මංජු ශ්‍රී හිමියන්", "අමරසේකරගේ 'සාතන්ගේ බලය' (Devil Dancer) වැනි කෘති බටහිර යථාර්ථවාදී ශෛලිය මනාව පෙන්වයි."),
        q("කැලණිය රජමහා විහාරයේ සුප්‍රකට නව බිතුසිතුවම් මාලාව (1927–1946) නිර්මාණය කළ ප්‍රවීණ දේශීය චිත්‍ර ශිල්පියා කවුද?", "සොලියස් මෙන්ඩිස් (Solias Mendis)", "ජෝර්ජ් කීට්", "ඩේවිඩ් පේන්ටර්", "ලයනල් වෙන්ඩ්ට්", "සීගිරි, අජන්තා හා මහනුවර සම්ප්‍රදායන් ඇසුරින් සොලියස් මෙන්ඩිස් කැලණි විහාර සිතුවම් නිර්මාණය කළේය."),
        q("ශ්‍රී ලංකාවේ ප්‍රකට කතෝලික පූජකවරයෙකුගේ පුත්‍රයෙකු වූ 'ඩේවිඩ් පේන්ටර්' (David Paynter) ලාංකේය කලාවට එක් කළ නවෝත්පාදනය කුමක්ද?", "බයිබල් කතා ලාංකේය රුවින් ඇඳීම", "චීන පෝසිලේන් සෙරමික් සෑදීම", "ලෝහ කැටයම් පමණක් නිර්මාණය", "වියුක්ත කළු පැල්ලම් ගෑම", "මහනුවර ත්‍රිත්ව විද්‍යාල දෙව්මැදුරේ හා ගාල්ලේ දෙව්මැදුරේ ඔහුගේ බිතුසිතුවම් ඉතා ප්‍රකටය."),
        q("ශ්‍රී ලංකාවේ නූතන වියුක්ත කලා ව්‍යාපාරයේ (Abstract Art) පුරෝගාමියෙකු හා සෞන්දර්ය අධ්‍යාපනඥයෙකු වූ ශිල්පියා කවුද?", "එච්.ඒ. කරුණාරත්න (H.A. Karunaratne)", "සොලියස් මෙන්ඩිස්", "දෙල්මඩ මූලාචාරී", "දේවරගම්පල හිමි", "ජපානයේ අධ්‍යාපනය ලැබූ එච්.ඒ. කරුණාරත්න කොලාජ්, තීන්ත හා දැව මුද්‍රණ වියුක්ත කලාවේ ප්‍රමුඛයා විය."),
        q("ශ්‍රී ලංකාවේ නූතන මූර්ති හා දැව කැටයම් කලාව ජාත්‍යන්තර තලයට ගෙන ගිය, කොළඹ පිහිටි නිදහස් මූර්ති ශිල්පියා කවුද?", "තිස්ස රණසිංහ (Tissa Ranasinghe)", "ඒ.සී.ජී.එස්. අමරසේකර", "ලයනල් වෙන්ඩ්ට්", "සෝරා", "ලෝකඩ හා ටෙරාකොටා මූර්ති හරහා සංස්කෘතික හා මානව තේමා නෙළූ තිස්ස රණසිංහ 'වළගම්බා' ආදී කෘති නිමවීය."),
        q("ශ්‍රී ලංකාවේ මහනුවර පාරම්පරික කලා ගුරුකුලය නවීකරණය කරමින් 'මහනුවර කලා සංගමය' හා ජන කලාව දියුණු කළ ශිල්පියා කවුද?", "ස්ටැන්ලි අබේසිංහ", "ජැක්සන් පොලොක්", "කැරවැජියෝ", "සැල්වදෝර් ඩාලි", "රජයේ කලායතනයේ විදුහල්පතිව සිටි ස්ටැන්ලි අබේසිංහ මහතා ලාංකේය කලා අධ්‍යාපනය නූතන මගකට යොමු කළේය."),
        q("ශ්‍රී ලංකාවේ විහාර බිතුසිතුවම් කලාවේ පහතරට හා නූතන ශෛලීන් අතර පාලමක් වූ මහගම සේකර හා සමකාලීන ප්‍රකට ශිල්පීන් අතර සුවිශේෂී වන්නේ කුමක්ද?", "දේශීය කාව්‍ය රසය හා ගැමි අත්දැකීම්", "රෝම යුද්ධ පමණක් ඇඳීම", "වීදුරු කර්මාන්තය පමණක් කිරීම", "ග්‍රීක කිරිගරුඬ ප්‍රතිමා කැපීම", "ලාංකේය සාහිත්‍ය හා දෘශ්‍ය කලා ක්ෂේත්‍රයන් 20 වන සියවසේදී අන්‍යෝන්‍ය වශයෙන් පෝෂණය විය."),
        q("ශ්‍රී ලංකාවේ නූතන වාස්තු විද්‍යාවේ (Tropical Modernism) ලෝක පූජිත පුරෝගාමියා වන 'ජෙෆ්රි බාවා' (Geoffrey Bawa) කලාත්මකව එක් කළේ මොනවාද?", "සාම්ප්‍රදායික මැදමිදුල් හා නූතන සරල බව", "මිසර පිරමීඩ ගොඩනැගිලි ක්‍රමය", "ග්‍රීක කිරිගරුඬ කුළුණු සම්ප්‍රදාය", "කළු වීදුරු අහස උස කුළුණු ක්‍රමය", "ලුනුගඟ උද්‍යානය, කණ්ඩලම හෝටලය හා පාර්ලිමේන්තු සංකීර්ණය බාවාගේ සුවිශේෂී වාස්තු කෘති වේ."),
        q("ජෙෆ්රි බාවාගේ සමීප කලා සහකරුවෙකු වූ, රෙදිපිළි හා බතික් කලාව නව මානයකට ගෙන ආ 'එනා ද සිල්වා' (Ena de Silva) සහ 'බාබරා සන්සෝනි' ප්‍රකට වන්නේ ඇයි?", "අත්යන්ත්‍ර රෙදිපිළි හා බතික් කලාව", "පෞරාණික කළුගල් දාගැබ් තැනීම", "කාර්මික ලෝහ යන්ත්‍ර නිපදවීම", "තෙල් සායම් බිතුසිතුවම් ඇඳීම", "අල්විස් පෙරේරා, එනා ද සිල්වා හා සන්සෝනි දේශීය වර්ණ හා අත්කම් ජාත්‍යන්තරයට ගෙන ගියහ."),
        q("1943 '43 කණ්ඩායමේ චිත්‍ර ශිල්පීන් සහ පසුකාලීන නූතන ලාංකේය චිත්‍ර ශිල්පීන් අතර පොදුවේ දැකිය හැකි ප්‍රවණතාව කුමක්ද?", "දේශීය පරිසරය නූතනව ප්‍රකාශ කිරීම", "විදේශීය ඡායාරූප පමණක් මුද්‍රණය", "සාම්ප්‍රදායික වර්ණ සම්පූර්ණ තහනම", "සියලු චිත්‍ර කළුගලින් පමණක් කැපීම", "බටහිර ශිල්ප ක්‍රම අන්ධ ලෙස අනුකරණය නොකර ලාංකේය ආත්මය මතු කිරීම ඔවුන්ගේ උරුමයයි.")
    )
}
